function checkLoginState(){FB.getLoginStatus(function(n){n.status==="connected"?statusChangeCallback(n):FB.login(function(n){statusChangeCallback(n)},{scope:"email"})})}function statusChangeCallback(n){n.status==="connected"?getUserData():console.log("User not authenticated or unable to determine authentication status.")}function getUserData(){FB.api("/me",{fields:"id,name,email"},function(n){n&&!n.error?(console.log("Successful login for: "+n.name),console.log("Email: "+n.email),console.log("ID: "+n.id),saveUserData(n)):console.log("Error fetching user data: ",n.error)})}function saveUserData(n){fetch("/LogSignInOut/SaveUserData",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({FacebookId:n.id,Name:n.name,Email:n.email})}).then(n=>{if(!n.ok)throw new Error("Network response was not ok");return n.json()}).then(n=>{n.success?(console.log("Dati salvati con successo."),window.history.back()):console.error("Errore durante il salvataggio dei dati:",n.errors)}).catch(n=>{console.error("Errore nella richiesta:",n)})}window.fbAsyncInit=function(){FB.init({appId:"1015689366876643",cookie:!0,xfbml:!0,version:"v20.0"});FB.AppEvents.logPageView()},function(n,t,i){var r,u=n.getElementsByTagName(t)[0];n.getElementById(i)||(r=n.createElement(t),r.id=i,r.src="https://connect.facebook.net/en_US/sdk.js",u.parentNode.insertBefore(r,u))}(document,"script","facebook-jssdk");